SELECT (
  COALESCE((SELECT SUM(total_cents) FROM orders WHERE status = 'paid'), 0) -
  COALESCE((SELECT SUM(amount_cents) FROM refunds), 0)
) / 100.0 AS net_revenue;

SELECT COUNT(*) AS order_count
FROM orders
WHERE status = 'paid';

SELECT SUM(total_cents) / 100.0 AS total_revenue
FROM orders
WHERE status = 'paid';

SELECT AVG(total_cents) / 100.0 AS average_order_value
FROM orders
WHERE status = 'paid';

